) VALUES (
    'lyric-vi-yeu-cu-dam-dau-min',
    'Lyric Vì Yêu Cứ Đâm Đầu - MIN',
    'MIN ft. Đen Vâu & JustaTee',
    'Nguyễn Hoàng Tôn, Đen Vâu, JustaTee',
    'Khắc Hưng',
    '2020',
    '03:00',
    'Bài hát ''Vì Yêu Cứ Đâm Đầu'' của MIN ft. Đen Vâu & JustaTee là một bản nhạc nhẹ nhàng, sâu lắng về tình yêu và sự dũng cảm trong việc theo đuổi cảm xúc của trái tim.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20V%C3%AC%20Y%C3%AAu%20C%E1%BB%A9%20%C4%90%C3%A2m%20%C4%90%E1%BA%A7u%20-%20MIN%20MIN%20ft.%20%C4%90en%20V%C3%A2u%20%26%20JustaTee',
    'https://open.spotify.com/search/Lyric%20V%C3%AC%20Y%C3%AAu%20C%E1%BB%A9%20%C4%90%C3%A2m%20%C4%90%E1%BA%A7u%20-%20MIN%20MIN%20ft.%20%C4%90en%20V%C3%A2u%20%26%20JustaTee',
    '',
    '#Ballad, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Ballad',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Vì Yêu Cứ Đâm Đầu'' của MIN ft. Đen Vâu & JustaTee là một bản nhạc nhẹ nhàng, sâu lắng về tình yêu và sự dũng cảm trong việc theo đuổi cảm xúc của trái tim.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Intro","content":"Qua nỗi sầu đêm nay\nTrăng gối đầu lên mây\nThêm chút rượu và men cuốn muộn phiền đi để tình thêm say\nĐôi mắt buồn sâu cay\nChan chứa tình lâu nay, oh boy\nKhông biết ở nơi đâu\nKhông biết được bao lâu\nChỉ muốn cùng anh đi đến tận cùng nơi đất trời thâm sâu\nHuhh-huh-huh-huh-huh\nVì yêu cứ đâm đầu (cứ đâm đầu)\nCứ đâm đầu (cứ đâm đầu)"},{"type":"Verse 1","content":"Ngay lúc nhìn, ngay lúc nhìn, ngay lúc nhìn, ngay lúc nhìn anh đôi phút\nTim đã vội, tim đã vội, tim đã vội, tim đã vội hơn đôi chút\nSorry em chẳng biết làm sao\nĐể thì giờ trôi phí là bao (oh-uh-oh, oh-oh)\nEm muốn được trói chặt trong vòng tay của anh\nEm muốn được nghe từng hơi thở đang bủa quanh\nXin hãy đừng, hãy đừng, hãy đừng, hãy đừng\nĐể em đợi (yeah, yeah)\nAy\nChạm lên bờ môi của em đỏ au\nTrò chuyện thật nhiều để cho rõ nhau (yah)\nChúng ta hoang dại như là cỏ lau (ah-hah)\nBỏ tiền bỏ bạc chứ không bỏ nhau"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Pop"}]'::jsonb,
    234,
    false,
    true
)
