INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-ke-tu-day-mylina',
    'Lyric Kể Từ Đây - Mylina',
    'Mylina''',
    'MYLINA',
    'DAO MUSIC ENTERTAINMENT',
    '2025',
    '03:18',
    'Bài hát ''Kể Từ Đây'' của Mylina'' là một bản ballad suy tư, tái hiện hành trình trưởng thành với những nỗi đau và bài học chân thực.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20K%E1%BB%83%20T%E1%BB%AB%20%C4%90%C3%A2y%20-%20Mylina%20Mylina''',
    'https://open.spotify.com/search/Lyric%20K%E1%BB%83%20T%E1%BB%AB%20%C4%90%C3%A2y%20-%20Mylina%20Mylina''',
    '',
    '#Ballad, #VietnameseMusic, #Heartbroken, #DeepEmotional, #Catharsis',
    'Ballad',
    'Thổn thức, đau đáu và cảm xúc giằng xé sau chia ly',
    'Bài hát ''Kể Từ Đây'' của Mylina'' là một bản ballad suy tư, tái hiện hành trình trưởng thành với những nỗi đau và bài học chân thực.',
    '["Piano solo mộc mạc","Cello da diết","Hiệu ứng Reverb sâu","Acoustic Beat"]'::jsonb,
    '[{"type":"Intro","content":"Một em bé ngu ngơ, tâm hồn em như trang giấy trắng\nBị vò nát trong một tích tắc\nNước mắt lưng tròng, thế giới xoay vòng\nMột em bé ngây thơ, tâm hồn em như trang giấy trắng\nChẳng biết mình làm gì sai, đã hủy hoại một ai\nCuộc đời em sẽ khó khăn nhiều thêm"},{"type":"Chorus","content":"Kể từ đây, những lắng lo sẽ không ngừng lại\nKể từ đây, cảm giác kia sẽ không dừng lại\nKể từ đây, em sẽ phải học cách đương đầu\nThay vì mong nó qua đi, sẽ chẳng qua đi\nNó chỉ lớn dần mà thôi, mà thôi\nÚhh-uhh huu, nó chỉ lớn dần mà thôi\nNước mắt lưng tròng, thế giới xoay vòng"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Pop"}]'::jsonb,
    1246,
    false,
    true
)
