INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-anh-la-ai-phuong-ly',
    'Lyric Anh Là Ai - Phương Ly',
    'Phương Ly',
    'Kiên Trần',
    'JustaTee',
    '2019',
    '04:05',
    'Bài hát ''Anh Là Ai'' của Phương Ly là một bản ballad R&B đầy hoài niệm, khắc họa nỗi nhớ da diết về một tình yêu mơ hồ và những câu hỏi day dứt về bản thân người ấy.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20Anh%20L%C3%A0%20Ai%20-%20Ph%C6%B0%C6%A1ng%20Ly%20Ph%C6%B0%C6%A1ng%20Ly',
    'https://open.spotify.com/search/Lyric%20Anh%20L%C3%A0%20Ai%20-%20Ph%C6%B0%C6%A1ng%20Ly%20Ph%C6%B0%C6%A1ng%20Ly',
    '',
    '#KPop, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'K-Pop',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Anh Là Ai'' của Phương Ly là một bản ballad R&B đầy hoài niệm, khắc họa nỗi nhớ da diết về một tình yêu mơ hồ và những câu hỏi day dứt về bản thân người ấy.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Intro","content":"Anh là ai nỗi nhớ khôn nguôi là anh\nMưa phùn rơi từ nơi quá khứ như đưa về đâu\nTôi đang ở đây cơn mưa làm rơi ướt vai vì ai, vì sao?\nGiờ anh ở đâu?"},{"type":"Chorus","content":"Anh là ai ngày mai nếu bước chân tôi cô đơn về\nAnh là ai mà tôi cứ luôn luôn đợi\nTừ khi nào biết yêu rồi\nTừ lâu tôi muốn nói về anh\nAnh là ai?\n\nKhiến nước mắt cứ rơi rơi nhẹ\nAnh là ai?\nĐã giết chết hết bao hy vọng\nAnh là ai?\nChắc có lẽ vẫn như xưa, chắc có lẽ mỗi tôi yêu anh\nAnh là ai?\n\nKhiến phút chốc trái tim rung động\nAnh là ai?\nMang yêu thương theo sau dường như\nLang thang trôi đi đâu tìm kiếm\nVì nhớ anh, thương anh, tìm anh nơi nỗi đau\nVì nhớ anh, thương anh, tìm anh trong giấc mơ"}]'::jsonb,
    '[{"name":"K-Pop"},{"name":"Ballad"},{"name":"Jazz"}]'::jsonb,
    1244,
    false,
    true
)
