INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-vet-thuong-fishy',
    'Lyric Vết Thương - Fishy',
    'Fishy',
    'Fishy',
    'Fishy',
    '2023',
    '03:45',
    'Bài hát ''Vết Thương'' là bản ballad indie năm 2023 của Fishy, kể về nỗi đau khi chứng kiến người mình yêu thương bên người khác. Với giai điệu nhẹ nhàng, lời ca sâu sắc, bài hát nhanh chóng viral trên TikTok và Spotify, chạm đến trái tim những ai từng trải qua tổn thương trong tình yêu.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20V%E1%BA%BFt%20Th%C6%B0%C6%A1ng%20-%20Fishy%20Fishy',
    'https://open.spotify.com/search/Lyric%20V%E1%BA%BFt%20Th%C6%B0%C6%A1ng%20-%20Fishy%20Fishy',
    '',
    '#Ballad, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Ballad',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Vết Thương'' là bản ballad indie năm 2023 của Fishy, kể về nỗi đau khi chứng kiến người mình yêu thương bên người khác. Với giai điệu nhẹ nhàng, lời ca sâu sắc, bài hát nhanh chóng viral trên TikTok và Spotify, chạm đến trái tim những ai từng trải qua tổn thương trong tình yêu.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Verse 1","content":"Và anh chỉ muốn ở trong cơn mơ ko muốn tỉnh dậy\nVì quá chán ghét cái thứ hạnh phúc quanh em hằng ngày\nNhưng em có vui như khi đã bên cạnh anh không\nĐôi khi cơn say khiến tâm trí anh chẳng hanh thông\nAnh cố đi qua nơi ta từng ngồi baby\nĐể thấy con tim anh không trọn vẹn\nThành phố đêm khuya khi không còn đèn\nAnh phải tìm từng dòng ký ức trôi qua mà anh tưởng chừng đâu đây\nGiá như anh yêu em thật nhiều đừng làm mình buồn lâu nay"},{"type":"Pre-Chorus","content":"It''s okay\nVà giá như it''s okay\nNếu như anh đủ lớn để chúc em luôn ngủ sớm\nAnh vẫn không quên khi bên nhau em từng nói rằng\nDù cho bức tranh đổi màu dù anh có đi nơi đâu\nThì em vẫn đứng ở đấy chờ (em vẫn đứng ở đấy chờ)\nNhững điều ấy làm anh mơ"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Chill"}]'::jsonb,
    450,
    false,
    true
)
