INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-dom-dom-jack-j97',
    'Lyric Đóm Đóm - Jack (J97)',
    'Jack (J97)',
    'Jack',
    'Jack',
    '2021',
    '05:38',
    'Bài hát ''Đóm Đóm'' là kiệt tác ballad năm 2021 của Jack (J97), dành tặng fandom Đóm và người con gái anh từng yêu. Với giai điệu da diết, ca từ đậm chất thơ miền Trung và hình ảnh ''đóm đóm'' tượng trưng cho tình yêu cháy mãi trong tim, bài hát đã chạm mốc hơn 168 triệu views, trở thành một trong những bản tình ca buồn được cover nhiều nhất Vpop thập kỷ.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20%C4%90%C3%B3m%20%C4%90%C3%B3m%20-%20Jack%20(J97)%20Jack%20(J97)',
    'https://open.spotify.com/search/Lyric%20%C4%90%C3%B3m%20%C4%90%C3%B3m%20-%20Jack%20(J97)%20Jack%20(J97)',
    '',
    '#Ballad, #VietnameseMusic, #RainyVibe, #Melancholy, #HealingRain',
    'Ballad',
    'Hoài niệm, da diết và man mác nỗi buồn chiều mưa',
    'Bài hát ''Đóm Đóm'' là kiệt tác ballad năm 2021 của Jack (J97), dành tặng fandom Đóm và người con gái anh từng yêu. Với giai điệu da diết, ca từ đậm chất thơ miền Trung và hình ảnh ''đóm đóm'' tượng trưng cho tình yêu cháy mãi trong tim, bài hát đã chạm mốc hơn 168 triệu views, trở thành một trong những bản tình ca buồn được cover nhiều nhất Vpop thập kỷ.',
    '["Piano trầm ấm","Guitar acoustic","Tiếng mưa nền (Rain Sound)","Dàn dây du dương"]'::jsonb,
    '[{"type":"Intro","content":"Em đi mất rồi, còn anh ở lại …\nNgười giờ còn đây không? Thuyền này còn liệu sang sông?\nBuổi chiều dài mênh mông, lòng người giờ hòa hay đông\nHồng mắt em cả bầu trời đỏ hoen\nTa như đứa trẻ ngây thơ, quên đi tháng ngày ngu ngơ"},{"type":"Verse 1","content":"Người là ngàn mây bay, mình là giọt sầu chia tay\nNgười cạn bầu không say, còn mình giãi bày trong đây\nNày gió ơi, đừng vội vàng, lắng nghe được không?"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Indie"},{"name":"R&B"}]'::jsonb,
    1680,
    false,
    true
)
