INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-anh-oi-anh-o-lai-chi-pu',
    'Lyric Anh Ơi Anh Ở Lại - Chi Pu',
    'Chi Pu',
    'Đạt G',
    'Đạt G',
    '2024',
    '04:32',
    'Bài hát ''Anh Ơi Anh Ở Lại'' là bản ballad comeback cực mạnh năm 2024 của Chi Pu, do Đạt G sáng tác. Với câu hát ''Anh ơi anh ở lại'' và hình ảnh cầu vồng – bông hoa tàn úa, bài hát nhanh chóng phủ sóng TikTok, chiếm mọi BXH và trở thành “quốc ca chia tay” mới của Gen Z. MV drama + giọng hát đầy cảm xúc đã giúp Chi Pu chứng minh sức hút không hề giảm sau nhiều năm.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20Anh%20%C6%A0i%20Anh%20%E1%BB%9E%20L%E1%BA%A1i%20-%20Chi%20Pu%20Chi%20Pu',
    'https://open.spotify.com/search/Lyric%20Anh%20%C6%A0i%20Anh%20%E1%BB%9E%20L%E1%BA%A1i%20-%20Chi%20Pu%20Chi%20Pu',
    '',
    '#Ballad, #VietnameseMusic, #Heartbroken, #DeepEmotional, #Catharsis',
    'Ballad',
    'Thổn thức, đau đáu và cảm xúc giằng xé sau chia ly',
    'Bài hát ''Anh Ơi Anh Ở Lại'' là bản ballad comeback cực mạnh năm 2024 của Chi Pu, do Đạt G sáng tác. Với câu hát ''Anh ơi anh ở lại'' và hình ảnh cầu vồng – bông hoa tàn úa, bài hát nhanh chóng phủ sóng TikTok, chiếm mọi BXH và trở thành “quốc ca chia tay” mới của Gen Z. MV drama + giọng hát đầy cảm xúc đã giúp Chi Pu chứng minh sức hút không hề giảm sau nhiều năm.',
    '["Piano solo mộc mạc","Cello da diết","Hiệu ứng Reverb sâu","Acoustic Beat"]'::jsonb,
    '[{"type":"Verse 1","content":"Lại là chia tay sau những lần không hiểu nhau\nTại vì thơ ngây bao nhiêu lần yêu vỡ nát nữa rồi\nTại vì hôm mưa anh đưa chiếc ô\nĐã làm trái tim em có cầu vồng\nMà cầu vồng chỉ có khi mưa vừa tan\nAnh cũng rời đi khi anh hết yêu"},{"type":"Pre-Chorus","content":"Vì sợ cô đơn nên em mặc kệ đúng sai\nMặc kệ anh có đưa đôi bàn tay ấm áp cho ai\nChỉ cầu xin anh em đã rất đau\nĐừng làm mắt em vương vấn thêm buồn\nDù có yêu trăm người mà trái tim không cười thì vẫn cô đơn vậy thôi"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Pop"}]'::jsonb,
    1850,
    false,
    true
)
