INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-noi-nay-co-anh-son-tung-m-tp',
    'Lyric Nơi Này Có Anh - Sơn Tùng M-TP',
    'Sơn Tùng M-TP',
    'Sơn Tùng M-TP',
    'Sơn Tùng M-TP',
    '2017',
    '04:20',
    'Bài hát ''Nơi Này Có Anh'' là bản tình ca kinh điển năm 2017 của Sơn Tùng M-TP, tự sáng tác và sản xuất. Với giai điệu pop/R&B ngọt ngào, lời ca lãng mạn về tình yêu bất diệt qua bốn mùa, bài hát đã đạt hơn 250 triệu views trên YouTube, trở thành biểu tượng Vpop, thường được dùng trong MV phim và cover hàng triệu lần bởi fan Sky.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20N%C6%A1i%20N%C3%A0y%20C%C3%B3%20Anh%20-%20S%C6%A1n%20T%C3%B9ng%20M-TP%20S%C6%A1n%20T%C3%B9ng%20M-TP',
    'https://open.spotify.com/search/Lyric%20N%C6%A1i%20N%C3%A0y%20C%C3%B3%20Anh%20-%20S%C6%A1n%20T%C3%B9ng%20M-TP%20S%C6%A1n%20T%C3%B9ng%20M-TP',
    '',
    '#Ballad, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Ballad',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Nơi Này Có Anh'' là bản tình ca kinh điển năm 2017 của Sơn Tùng M-TP, tự sáng tác và sản xuất. Với giai điệu pop/R&B ngọt ngào, lời ca lãng mạn về tình yêu bất diệt qua bốn mùa, bài hát đã đạt hơn 250 triệu views trên YouTube, trở thành biểu tượng Vpop, thường được dùng trong MV phim và cover hàng triệu lần bởi fan Sky.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Verse 1","content":"Em là ai từ đâu bước đến nơi đây dịu dàng chân phương\nEm là ai tựa như ánh nắng ban mai ngọt ngào trong sương\nNgắm em thật lâu\nCon tim anh yếu mềm\nĐắm say từ phút đó\nTừng giây trôi yêu thêm\n\nBao ngày qua bình minh đánh thức xua tan bộn bề nơi anh (bộn về nơi anh)\nBao ngày qua niềm thương nỗi nhớ bay theo bầu trời trong xanh (bầu trời trong xanh)\nLiếc đôi hàng mi (hàng mi)\nMong manh anh thẫn thờ (thẫn thờ)\nMuốn hôn nhẹ mái tóc\nBờ môi em anh mơ"},{"type":"Chorus","content":"Cầm tay anh dựa vai anh\nKề bên anh nơi này có anh\nGió mang câu tình ca\nNgàn ánh sao vụt qua nhẹ ôm lấy em (yêu em thương em con tim anh chân thành)\nCầm tay anh dựa vai anh\nKề bên anh nơi này có anh\nKhép đôi mi thật lâu\nNguyện mãi bên cạnh nhau yêu say đắm như ngày đầu"}]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Pop"}]'::jsonb,
    2500,
    false,
    true
)
