INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-nang-am-trong-tim-duongg',
    'Lyric Nắng Ấm Trong Tim - Duongg',
    'Duongg',
    'Duongg, T.R.I',
    'Duongg Entertainment',
    '2024',
    '04:28',
    'Bài hát ''Nắng Ấm Trong Tim'' là bản ballad hit cuối 2024 của Duongg, do chính anh sáng tác và sản xuất. Với giai điệu ngọt ngào, lời ca về tình yêu ấm áp vượt qua mọi khó khăn, bài hát nhanh chóng lan tỏa trên TikTok và YouTube, trở thành hiện tượng âm nhạc đầu năm 2025. MV lãng mạnh cùng giọng hát truyền cảm đã giúp Duongg khẳng định vị thế trong làng nhạc Việt.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20N%E1%BA%AFng%20%E1%BA%A4m%20Trong%20Tim%20-%20Duongg%20Duongg',
    'https://open.spotify.com/search/Lyric%20N%E1%BA%AFng%20%E1%BA%A4m%20Trong%20Tim%20-%20Duongg%20Duongg',
    '',
    '#Pop, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Pop',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Nắng Ấm Trong Tim'' là bản ballad hit cuối 2024 của Duongg, do chính anh sáng tác và sản xuất. Với giai điệu ngọt ngào, lời ca về tình yêu ấm áp vượt qua mọi khó khăn, bài hát nhanh chóng lan tỏa trên TikTok và YouTube, trở thành hiện tượng âm nhạc đầu năm 2025. MV lãng mạnh cùng giọng hát truyền cảm đã giúp Duongg khẳng định vị thế trong làng nhạc Việt.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Verse 1","content":"Một chiều em đến con tim hoá ngập tràn\nCùng bao si mê chẳng muộn màng\nCó tiếng nói bên tai sẽ chẳng thể biến tan\nGiờ lòng chỉ biết tơ vương đến một người\nỞ bên em không phải gượng cười\nThấy trước mắt đôi ta sẽ vui với hiện tại"},{"type":"Pre-Chorus","content":"Biển tình mênh mông có ánh dương\nSẽ chiếu sáng nơi thánh đường\nKhẽ dẫn lối đôi chân ta đi chung một hướng\nĐường đời đôi lúc sẽ có những nhấp nhô\nHệt đại dương mênh mông có sóng xô\nĐừng lo lắng vì luôn có anh trên tàu"}]'::jsonb,
