INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-tu-thich-thich-thanh-thuong-thuong',
    'Lyric Từ Thích Thích Thành Thương Thương - Amee ft. Hoàng Dũng',
    'Amee ft. Hoàng Dũng',
    'Kai Đinh, Hứa Kim Tuyền, TDK',
    'St.319',
    '2020',
    '04:05',
    'Bài hát ''Từ Thích Thích Thành Thương Thương'' là bản hit ballad ngọt ngào năm 2020 của Amee ft. Hoàng Dũng, kể về hành trình từ ''thích thích'' đến ''thương thương'' đầy ngại ngùng và đơn phương. Với giai điệu da diết và câu bridge viral khắp nơi, bài hát nhanh chóng chạm mốc hàng chục triệu view, trở thành ''quốc ca crush'' của thế hệ trẻ Vpop.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20T%E1%BB%AB%20Th%C3%ADch%20Th%C3%ADch%20Th%C3%A0nh%20Th%C6%B0%C6%A1ng%20Th%C6%B0%C6%A1ng%20-%20Amee%20ft.%20Ho%C3%A0ng%20D%C5%A9ng%20Amee%20ft.%20Ho%C3%A0ng%20D%C5%A9ng',
    'https://open.spotify.com/search/Lyric%20T%E1%BB%AB%20Th%C3%ADch%20Th%C3%ADch%20Th%C3%A0nh%20Th%C6%B0%C6%A1ng%20Th%C6%B0%C6%A1ng%20-%20Amee%20ft.%20Ho%C3%A0ng%20D%C5%A9ng%20Amee%20ft.%20Ho%C3%A0ng%20D%C5%A9ng',
    '',
    '#Pop, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Pop',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Từ Thích Thích Thành Thương Thương'' là bản hit ballad ngọt ngào năm 2020 của Amee ft. Hoàng Dũng, kể về hành trình từ ''thích thích'' đến ''thương thương'' đầy ngại ngùng và đơn phương. Với giai điệu da diết và câu bridge viral khắp nơi, bài hát nhanh chóng chạm mốc hàng chục triệu view, trở thành ''quốc ca crush'' của thế hệ trẻ Vpop.',
