INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-tinh-yeu-cham-tre-grey-d',
    'Lyric Tình Yêu Chậm Trễ - Grey D',
    'Grey D',
    'Grey D',
    'St.319',
    '2023',
    '04:37',
    'Bài hát ''Tình Yêu Chậm Trễ (Live Piano Ver.)'' là phiên bản acoustic sâu lắng của Grey D, phát hành cuối 2023. Với chỉ cây đàn piano và giọng hát chân thành, bản live piano này đã chạm đến trái tim khán giả, viral mạnh trên YouTube và Spotify, vượt 5 triệu lượt nghe chỉ sau 2 năm, trở thành bản ballad buồn về những tình yêu đến muộn mà ai cũng từng trải qua.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20T%C3%ACnh%20Y%C3%AAu%20Ch%E1%BA%ADm%20Tr%E1%BB%85%20-%20Grey%20D%20Grey%20D',
    'https://open.spotify.com/search/Lyric%20T%C3%ACnh%20Y%C3%AAu%20Ch%E1%BA%ADm%20Tr%E1%BB%85%20-%20Grey%20D%20Grey%20D',
    '',
    '#Pop, #VietnameseMusic, #RainyVibe, #Melancholy, #HealingRain',
    'Pop',
    'Hoài niệm, da diết và man mác nỗi buồn chiều mưa',
    'Bài hát ''Tình Yêu Chậm Trễ (Live Piano Ver.)'' là phiên bản acoustic sâu lắng của Grey D, phát hành cuối 2023. Với chỉ cây đàn piano và giọng hát chân thành, bản live piano này đã chạm đến trái tim khán giả, viral mạnh trên YouTube và Spotify, vượt 5 triệu lượt nghe chỉ sau 2 năm, trở thành bản ballad buồn về những tình yêu đến muộn mà ai cũng từng trải qua.',
    '["Piano trầm ấm","Guitar acoustic","Tiếng mưa nền (Rain Sound)","Dàn dây du dương"]'::jsonb,
    '[{"type":"Intro","content":"Anh thường nghĩ mình quên mất rồi\nThời gian ngỡ trôi sẽ cách lòng\nAnh thường nghĩ cảm xúc nhất thời\nMà đâu biết say một đời"},{"type":"Pre-Chorus","content":"Rồi khi đã biết là người em vốn thiết tha\nChẳng phải nơi này mà từ một nơi xa\nLặng nghe em nói, lòng anh đau nhói\nCứ trách sao không nhận ra tình yêu sớm hơn"}]'::jsonb,
    '[{"name":"Pop"},{"name":"Ballad"},{"name":"Rap / Hip-hop"}]'::jsonb,
    2343,
    false,
