INSERT INTO public.lyrics_music (
    slug, title, artist, composer, producer, year, duration, "desc",
    image_base64, singer_photo_base64, audio_url, spotify_url, spotify_track_id,
    vibe, genre, mood, story, instruments, lyrics, categories, views, is_current, is_active
) VALUES (
    'lyric-bao-tien-mot-mo-binh-yen',
    'Lyric Bao Tiền Một Mớ Bình Yên - 14 Casper ft. Bon',
    '14 Casper',
    '14 Casper',
    '14 Casper',
    '2020',
    '04:15',
    'Bài hát ''Bao Tiền Một Mớ Bình Yên'' là bản ballad truyền cảm hứng của 14 Casper ft. Bon năm 2020, nói về hành trình tìm kiếm bình yên giữa bộn bề cuộc sống. Với câu hỏi day dứt “Cần bao nhiêu tiền đổi một mớ bình yên?” và thông điệp tự yêu thương bản thân, bài hát nhanh chóng chạm đến trái tim khán giả, vượt 15 triệu view và trở thành ''quốc ca'' động viên cho những ai đang mệt mỏi, lạc lối giữa guồng quay công việc.',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'https://open.spotify.com/search/Lyric%20Bao%20Ti%E1%BB%81n%20M%E1%BB%99t%20M%E1%BB%9B%20B%C3%ACnh%20Y%C3%AAn%20-%2014%20Casper%20ft.%20Bon%2014%20Casper',
    'https://open.spotify.com/search/Lyric%20Bao%20Ti%E1%BB%81n%20M%E1%BB%99t%20M%E1%BB%9B%20B%C3%ACnh%20Y%C3%AAn%20-%2014%20Casper%20ft.%20Bon%2014%20Casper',
    '',
    '#Pop, #VietnameseMusic, #RomanticVibe, #SweetMelody, #LoveSongs',
    'Pop',
    'Ngọt ngào, say đắm và lãng mạn nhẹ nhàng',
    'Bài hát ''Bao Tiền Một Mớ Bình Yên'' là bản ballad truyền cảm hứng của 14 Casper ft. Bon năm 2020, nói về hành trình tìm kiếm bình yên giữa bộn bề cuộc sống. Với câu hỏi day dứt “Cần bao nhiêu tiền đổi một mớ bình yên?” và thông điệp tự yêu thương bản thân, bài hát nhanh chóng chạm đến trái tim khán giả, vượt 15 triệu view và trở thành ''quốc ca'' động viên cho những ai đang mệt mỏi, lạc lối giữa guồng quay công việc.',
    '["Guitar đệm ấm áp","Electric Piano","Synthpad nhẹ nhàng","Bass mềm mại"]'::jsonb,
    '[{"type":"Verse 1","content":"Mười giờ văn phòng vẫn sáng đèn\nLại một hôm làm thâu suốt đêm\nBàn chân đau mỏi nhức\nTựa lưng em chợp mắt\nDặn lòng vì cuộc sống êm đẹp\nHạnh phúc không đâu cách xa\nMà ta cứ đi tìm\nVậy xin em một lần\nTự yêu thương lấy mình\nMột ngày em được mấy bữa cơm\nĐợt này công việc có tốt hơn\nCòn ai hay gièm pha\nCòn ai luôn rầy la mà xót xa oà lên khóc vô vọng"},{"type":"Pre-Chorus","content":"Cành lá đông qua sẽ rơi\nKhổ đau sẽ vơi đời buồn sẽ qua\nMưa tạnh mây tan trời quang\nXin đừng buông xuôi dễ dàng"}]'::jsonb,
