INSERT INTO public.playlists_music (
    slug, title, "desc", description, keywords, categories,
    image, banner, songs, mood, final, views, date
) VALUES (
    'playlist-ky-niem-tinh-yeu-nhung-khoanh-khac-cua-hai-ta',
    'Playlist Kỷ Niệm Tình Yêu: Những Khoảnh Khắc Của Hai Ta',
    'Khám phá playlist kỷ niệm tình yêu Những Khoảnh Khắc Của Hai Ta – nơi lưu giữ những ký ức đẹp nhất của hai người: từ rung động đầu tiên, những ngày tháng ngọt ngào, đến nỗi nhớ da diết khi xa cách. Mỗi bài hát là một mảnh ghép kỷ niệm, giúp bạn sống lại những khoảnh khắc yêu thương đã từng có.',
    'Playlist kỷ niệm tình yêu Những Khoảnh Khắc Của Hai Ta – nơi lưu giữ những ký ức đẹp nhất của hai người: từ rung động đầu tiên, những ngày tháng ngọt ngào, đến nỗi nhớ da diết khi xa cách. Mỗi bài hát là một mảnh ghép kỷ niệm, giúp bạn sống lại những khoảnh khắc yêu thương đã từng có. Dành cho ai đang yêu, đang nhớ, hoặc đang tìm lại những kỷ niệm cũ – đây là cuốn nhật ký âm nhạc của tình yêu. Từ ''Tháng Năm'' gợi nhớ tuổi trẻ, đến ''Tháng Mấy Em Nhớ Anh?'' đầy day dứt, playlist này như một dòng sông kỷ niệm, đưa bạn trở về những ngày tháng không thể nào quên. Hãy bật lên, nhắm mắt, và để nhạc kể lại câu chuyện tình yêu của bạn – những kỷ niệm vẫn còn nguyên vẹn trong tim.',
    '["playlist kỷ niệm tình yêu","những khoảnh khắc của hai ta","nhạc tình yêu","nhạc ballad","nhạc lofi","nhạc nhẹ nhàng","nhạc Việt","playlist cảm xúc"]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Playlist cảm xúc"}]'::jsonb,
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    '[{"name":"Tháng Năm","desc":"Bản tình ca gợi kỷ niệm thanh xuân rực rỡ nhất. ''Tháng Năm'' như cuốn phim cũ, đưa bạn trở về những ngày đạp xe dưới hàng cây, ánh mắt đầu tiên, và nụ cười ngại ngùng. Một kỷ niệm không phai trong trái tim ai từng yêu.","youtube":"https://www.youtube.com/watch?v=sG9JhIRuTkA"},{"name":"Một Triệu Like","desc":"Tình yêu giản đơn nhưng đầy kỷ niệm: tin nhắn đêm khuya, hẹn hà vụng về, và những khoảnh khắc khiến tim rung lên. ''Một Triệu Like'' là lời nhắc rằng kỷ niệm đẹp nhất chính là sự chân thành.","youtube":"https://www.youtube.com/watch?v=oigiXW6XyCQ"},{"name":"Có Em","desc":"Chỉ cần có nhau, mọi kỷ niệm đều trở nên ý nghĩa. ''Có Em'' là lời khẳng định rằng tình yêu biến những ngày bình thường thành kỷ niệm đáng nhớ mãi mãi.","youtube":"https://www.youtube.com/watch?v=DcCISK3sCYg"},{"name":"Vì Yêu Cứ Đâm Đầu","desc":"Cuồng nhiệt, liều lĩnh, và đầy kỷ niệm đẹp dù có đau. ''Vì Yêu Cứ Đâm Đầu'' là tuyên ngôn của những trái tim dám yêu hết mình – để lại những kỷ niệm không thể xóa nhòa.","youtube":"https://www.youtube.com/watch?v=EWz4fITO5qg"},{"name":"Phía Sau Em","desc":"Kỷ niệm của một người đứng phía sau lặng lẽ yêu. ''Phía Sau Em'' là nỗi nhớ thầm lặng, là những ánh mắt chưa từng nói thành lời – một kỷ niệm buồn nhưng đẹp.","youtube":"https://www.youtube.com/watch?v=LklFoy_a3bA"},{"name":"Lạ Lùng","desc":"Kỷ niệm mơ hồ, khó nắm bắt như giấc mơ. ''Lạ Lùng'' là những cảm xúc không tên, những khoảnh khắc yêu thương thoáng qua nhưng mãi khắc sâu trong tim.","youtube":"https://www.youtube.com/watch?v=jv7WQeIPGjY"},{"name":"Tháng Mấy Em Nhớ Anh?","desc":"Nỗi nhớ theo từng tháng, từng mùa – một kỷ niệm không thể nguôi. ''Tháng Mấy Em Nhớ Anh?'' là lá thư tình gửi người cũ, đầy day dứt và hoài niệm.","youtube":"https://www.youtube.com/watch?v=lxFmeBhoA1Y"},{"name":"Em Không Sai, Chúng Ta Sai","desc":"Kỷ niệm của một cuộc chia tay không ai muốn. ''Em Không Sai, Chúng Ta Sai'' là lời chấp nhận nhẹ nhàng, rằng kỷ niệm vẫn đẹp dù tình yêu đã hết.","youtube":"https://www.youtube.com/watch?v=iwGuiSnr2Qc"},{"name":"3107 - 3","desc":"Lofi buồn cho những đêm khuya ôm kỷ niệm. ''3107 - 3'' là không gian tĩnh lặng để bạn thả hồn vào những ký ức cũ, những người đã từng ở bên.","youtube":"https://www.youtube.com/watch?v=kfw7MYah2nU"},{"name":"Hơn Cả Yêu","desc":"Kỷ niệm không chỉ là yêu, mà là sự hiện diện. ''Hơn Cả Yêu'' là lời hứa rằng những khoảnh khắc bên nhau sẽ mãi là kỷ niệm đẹp nhất.","youtube":"https://www.youtube.com/watch?v=__kGJZ-kPno"},{"name":"Anh Đã Quen Với Cô Đơn","desc":"Kỷ niệm sau chia tay: học cách sống chung với nỗi nhớ. ''Anh Đã Quen Với Cô Đơn'' là hành trình chữa lành, nơi kỷ niệm vẫn còn nhưng trái tim đã mạnh mẽ hơn.","youtube":"https://www.youtube.com/watch?v=X7sSE3yCNLI"},{"name":"Một Nhà","desc":"Kết thúc bằng hy vọng: kỷ niệm sẽ dẫn đến một mái ấm. ''Một Nhà'' là giấc mơ về tương lai, nơi mọi kỷ niệm đều trở thành nền tảng cho hạnh phúc.","youtube":"https://www.youtube.com/watch?v=TKlXc3iywoM"}]'::jsonb,
    'Romantic',
    'Playlist kỷ niệm tình yêu Những Khoảnh Khắc Của Hai Ta không chỉ là âm nhạc – mà là một hành trình trở về với những kỷ niệm đẹp nhất của bạn và người ấy. Từ những rung động đầu tiên trong ''Tháng Năm'', đến nỗi nhớ da diết trong ''Tháng Mấy Em Nhớ Anh?'', mỗi bài hát là một mảnh ghép kỷ niệm, giúp bạn sống lại từng khoảnh khắc yêu thương. Dù bạn đang hạnh phúc bên người ấy, đang nhớ một người cũ, hay đang tìm lại chính mình trong những ký ức xưa – playlist này sẽ là người bạn đồng hành. Hãy bật lên, để những giai điệu dẫn bạn qua dòng sông kỷ niệm, nơi mọi cảm xúc đều được trân trọng. Vì tình yêu không chỉ là hiện tại, mà còn là những kỷ niệm mãi mãi ở lại trong tim. Đây là nơi để bạn tìm lại những khoảnh khắc của hai ta – đẹp đẽ, ngọt ngào, và không thể nào quên.',
    1200,
    '2025-10-20'
)
ON CONFLICT (slug) DO UPDATE SET
