INSERT INTO public.playlists_music (
    slug, title, "desc", description, keywords, categories,
    image, banner, songs, mood, final, views, date
) VALUES (
    'playlist-thon-thuc-tinh-yeu-mot-not-tram-trong-tim',
    'Playlist Thổn Thức Tình Yêu: Một Nốt Trầm Trong Tim',
    'Khám phá playlist thổn thức tình yêu Một Nốt Trầm Trong Tim – nơi những giai điệu buồn nhẹ, sâu lắng, chạm vào trái tim đang rung lên từng nhịp thổn thức. Dành cho những đêm cô đơn, khi bạn muốn nghe lại tiếng lòng mình: nỗi nhớ da diết, ký ức phai mờ, và những cảm xúc không thể nói thành lời. Mỗi bài hát là một nốt trầm thổn thức, không bi lụy, mà dịu dàng, chân thành – như một người bạn lặng lẽ đồng hành.',
    'Playlist thổn thức Một Nốt Trầm Trong Tim – nơi những giai điệu buồn nhẹ, sâu lắng, chạm vào trái tim đang rung lên từng nhịp thổn thức. Dành cho những đêm cô đơn, khi bạn muốn nghe lại tiếng lòng mình: nỗi nhớ da diết, ký ức phai mờ, và những cảm xúc không thể nói thành lời. Mỗi bài hát là một nốt trầm thổn thức, không bi lụy, mà dịu dàng, chân thành – như một người bạn lặng lẽ đồng hành. Từ ''Chạy Về Khóc Với Anh'' đầy nước mắt, đến ''Đôi Lời Tình Ca'' như tiếng thở dài cuối cùng, playlist này là không gian để bạn thả hồn vào dòng cảm xúc thổn thức, để bạn hiểu rằng: dù tình yêu đã xa, trái tim vẫn còn biết rung động. Hãy bật lên – để những nốt nhạc buồn làm bạn thổn thức, rồi lại nhẹ nhàng chữa lành.',
    '["playlist thổn thức tình yêu","một nốt trầm trong tim","nhạc buồn nhẹ","nhạc ballad","nhạc Việt","playlist cảm xúc","nhạc sâu lắng"]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Playlist cảm xúc"}]'::jsonb,
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    '[{"name":"Chạy Về Khóc Với Anh","desc":"Mở đầu bằng một bản ballad thổn thức, ''Chạy Về Khóc Với Anh'' là tiếng lòng vỡ òa của trái tim tan vỡ. Giai điệu như vòng tay ôm lấy nỗi đau, lời ca như dòng nước mắt lặng lẽ rơi – dành cho ai từng chạy qua đêm đen, chỉ để tìm một nơi trút bỏ nỗi thổn thức trong tim.","youtube":"https://www.youtube.com/watch?v=EBpp2VTSI2Q"},{"name":"Anh Đã Quen Với Cô Đơn","desc":"Nốt trầm thổn thức nhất của playlist. ''Anh Đã Quen Với Cô Đơn'' là lời tự sự của một người học cách sống chung với nỗi nhớ. Giai điệu buồn như tiếng thở dài, nhưng vẫn đẹp – vì trong cô đơn, trái tim vẫn còn biết thổn thức.","youtube":"https://www.youtube.com/watch?v=X7sSE3yCNLI"},{"name":"Đông Kiếm Em","desc":"Giữa mùa đông lạnh buốt, ''Đông Kiếm Em'' là nỗi thổn thức không lời. Giai điệu như tuyết rơi, lời ca như gió lạnh – chạm vào những góc khuất của trái tim đang tìm kiếm một bóng hình đã xa.","youtube":"https://www.youtube.com/watch?v=h6RONxjPBf4"},{"name":"Nàng Thơ","desc":"Dịu dàng như một bài thơ buồn, ''Nàng Thơ'' là nốt nhạc thổn thức về người con gái từng là cả thế giới. Dù đã xa, cô ấy vẫn khiến tim bạn rung lên từng nhịp – nhẹ nhàng, nhưng sâu đậm.","youtube":"https://www.youtube.com/watch?v=Zzn9-ATB9aU"},{"name":"Từ Ngày Em Đến","desc":"Tình yêu đến rồi đi, để lại trái tim thổn thức. ''Từ Ngày Em Đến'' là câu chuyện về sự thay đổi – buồn nhẹ, nhưng chân thật. Một nốt trầm khiến bạn muốn nhìn lại hành trình của chính mình.","youtube":"https://www.youtube.com/watch?v=AmvA-XJF0j8"},{"name":"Đi Qua Mùa Hạ","desc":"Mùa hạ trôi qua, mang theo tuổi trẻ và những thổn thức đầu đời. ''Đi Qua Mùa Hạ'' như cuốn phim cũ – rực rỡ, nhưng giờ chỉ còn là ký ức khiến tim bạn rung lên từng nhịp.","youtube":"https://www.youtube.com/watch?v=wXsBaFCfXb0"},{"name":"Người Ta Nói","desc":"Lời thì thầm của người đời, nỗi đau trong tình yêu – ''Người Ta Nói'' là nốt nhạc thổn thức mộc mạc, gần gũi. Dành cho ai từng nghe những lời xì xào, và vẫn giữ nguyên cảm xúc trong tim.","youtube":"https://www.youtube.com/watch?v=AZNAv3rpa4U"},{"name":"Cứ Thế Rời Xa","desc":"Buông tay không lời, chỉ còn lại trái tim thổn thức. ''Cứ Thế Rời Xa'' là lời tự sự day dứt, nhưng mạnh mẽ – dành cho ai từng yêu sâu đậm, rồi lặng lẽ bước tiếp.","youtube":"https://www.youtube.com/watch?v=zQwKxVCR1y8"},{"name":"Chỉ Là Không Cùng Nhau","desc":"Song ca buồn đến nao lòng, ''Chỉ Là Không Cùng Nhau'' là đỉnh cao của sự thổn thức. Hai giọng hát hòa quyện, kể về một tình yêu đẹp nhưng không thể tiếp tục – khiến tim bạn rung lên từng nhịp đau.","youtube":"https://www.youtube.com/watch?v=UqKVL56IJB8"},{"name":"Thật Ra Em Chẳng Thương Anh Như Vậy Đâu","desc":"Lời thú nhận muộn màng, trái tim thổn thức giữa sự thật và ảo tưởng. ''Thật Ra Em Chẳng Thương Anh Như Vậy Đâu'' là nốt trầm sâu sắc, chạm vào những cảm xúc mâu thuẫn nhất.","youtube":"https://www.youtube.com/watch?v=90sYCPQTZ40"},{"name":"Như Anh Đã Thấy Em","desc":"Một bức thư tình chưa gửi, ''Như Anh Đã Thấy Em'' là nốt nhạc thổn thức mơ màng. Giai điệu như giấc mơ, lời ca như ký ức – dành cho ai vẫn còn giữ hình bóng ấy trong tim.","youtube":"https://www.youtube.com/watch?v=cPbp2iFaZRo"},{"name":"Đôi Lời Tình Ca","desc":"Kết thúc bằng một tiếng thở dài dịu dàng, ''Đôi Lời Tình Ca'' là nốt trầm thổn thức cuối cùng. Không bi lụy, chỉ là lời tạm biệt nhẹ nhàng – để bạn bước tiếp với trái tim đã được chữa lành.","youtube":"https://www.youtube.com/watch?v=8Tcj6xoQ_xc"}]'::jsonb,
    'Melancholic',
    'Playlist thổn thức Một Nốt Trầm Trong Tim không chỉ là âm nhạc – mà là một hành trình lắng nghe trái tim mình. Mỗi bài hát là một nhịp thổn thức: từ ''Chạy Về Khóc Với Anh'' đầy nước mắt, đến ''Đôi Lời Tình Ca'' như lời từ biệt dịu dàng. Đây là không gian dành cho những tâm hồn nhạy cảm, những ai muốn thả mình vào dòng cảm xúc buồn nhẹ, sâu lắng, và tìm thấy sự an ủi trong chính nỗi đau. Dù bạn đang cô đơn, đang nhớ, hay đang học cách buông tay – playlist này sẽ đồng hành cùng bạn, giúp bạn hiểu rằng: thổn thức không phải là yếu đuối, mà là bằng chứng rằng bạn đã từng yêu rất thật. Hãy bật lên vào một đêm yên ắng, để những nốt trầm này chạm vào tim bạn, làm bạn thổn thức, rồi nhẹ nhàng… chữa lành.',
    850,
    '2025-10-20'
)
ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    "desc" = EXCLUDED."desc",
