INSERT INTO public.playlists_music (
    slug, title, "desc", description, keywords, categories,
    image, banner, songs, mood, final, views, date
) VALUES (
    'playlist-truong-thanh-khi-ta-du-lon-de-hieu-minh',
    'Playlist Trưởng Thành: Khi Ta Đủ Lớn Để Hiểu Mình',
    'Khám phá playlist trưởng thành Khi Ta Đủ Lớn Để Hiểu Mình – nơi âm nhạc kể câu chuyện về hành trình lớn lên: từ những tổn thương đầu đời, những lần vấp ngã, đến khoảnh khắc tỉnh thức và biết yêu thương chính mình. Đây không phải playlist để buồn, mà để hiểu – hiểu bản thân, hiểu cuộc đời, hiểu rằng trưởng thành là học cách bước đi dù đau. Mỗi bài hát là một cột mốc: từ rap tự sự của Đen Vâu, ballad day dứt của Vũ, đến những giai điệu nhẹ nhàng chữa lành. Dành cho ai từng lạc lối, từng khóc trong đêm, từng nghĩ mình không thể vượt qua – nhưng rồi vẫn đứng dậy. Trưởng thành không phải là không đau, mà là đau rồi vẫn chọn đi tiếp. Hãy bật playlist này khi bạn cần một người bạn âm nhạc để đồng hành trên hành trình trưởng thành – để bạn nhận ra: bạn đã lớn hơn bạn nghĩ.',
    'Playlist trưởng thành Khi Ta Đủ Lớn Để Hiểu Mình – nơi âm nhạc kể câu chuyện về hành trình lớn lên: từ những tổn thương đầu đời, những lần vấp ngã, đến khoảnh khắc tỉnh thức và biết yêu thương chính mình. Đây không phải playlist để buồn, mà để hiểu – hiểu bản thân, hiểu cuộc đời, hiểu rằng trưởng thành là học cách bước đi dù đau. Mỗi bài hát là một cột mốc: từ rap tự sự của Đen Vâu, ballad day dứt của Vũ, đến những giai điệu nhẹ nhàng chữa lành. Dành cho ai từng lạc lối, từng khóc trong đêm, từng nghĩ mình không thể vượt qua – nhưng rồi vẫn đứng dậy. Trưởng thành không phải là không đau, mà là đau rồi vẫn chọn đi tiếp. Hãy bật playlist này khi bạn cần một người bạn âm nhạc để đồng hành trên hành trình trưởng thành – để bạn nhận ra: bạn đã lớn hơn bạn nghĩ.',
    '["playlist trưởng thành","khi ta đủ lớn để hiểu mình","nhạc rap tự sự","nhạc ballad","nhạc nhẹ nhàng","nhạc Việt","playlist cảm xúc","nhạc chữa lành"]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Ballad"},{"name":"Playlist cảm xúc"}]'::jsonb,
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    '[{"name":"Trưởng Thành","desc":"Mở đầu bằng tuyên ngôn trưởng thành mạnh mẽ nhất: ''Trưởng thành là khi ta học cách chịu trách nhiệm với chính mình''. Giai điệu rap sâu lắng, lời ca như cuốn nhật ký – kể về những lần sai lầm, những lần mất mát, và khoảnh khắc nhận ra: trưởng thành bắt đầu từ việc dám đối diện.","youtube":"https://www.youtube.com/watch?v=UVbv-PJXm14"},{"name":"Bước Qua Nhau","desc":"Giai điệu buồn man mác, lời ca như tiếng thở dài: ''Ta bước qua nhau để trưởng thành''. Một bài hát về sự buông tay không phải vì hết yêu, mà vì cần lớn lên. Trưởng thành là biết buông đúng lúc.","youtube":"https://www.youtube.com/watch?v=3rIZ9o1Hq9E"},{"name":"Mang Tiền Về Cho Mẹ","desc":"Trưởng thành không chỉ là tự lập, mà là biết yêu thương gia đình. Lời rap chân thật, mạnh mẽ: ''Trưởng thành là khi con biết mang tiền về cho mẹ, chứ không chỉ mang nỗi lo về nhà''. Một bài học lớn về trách nhiệm.","youtube":"https://www.youtube.com/watch?v=UVbv-PJXm14"},{"name":"Thức Giấc","desc":"Khoảnh khắc tỉnh thức: ''Mọi ký ức chỉ để nhớ, không để quay lại''. Giai điệu nhẹ nhàng, lời ca sâu sắc – trưởng thành là biết buông quá khứ để bước tới tương lai.","youtube":"https://www.youtube.com/watch?v=R3trO4a49go"},{"name":"Trốn Tìm","desc":"Rap chiêm nghiệm về sự thay đổi: ''Ai rồi cũng khác, chỉ là có dám đối diện hay không''. Trưởng thành là chấp nhận bản thân đã khác, và vẫn yêu thương phiên bản mới.","youtube":"https://www.youtube.com/watch?v=Ws-QlpSltr8"},{"name":"Có Chàng Trai Viết Lên Cây","desc":"Hồi ức tuổi trẻ: ''Chàng trai ấy từng viết tên em lên cây, giờ cây đã lớn, người cũng trưởng thành''. Một bài hát dịu dàng về hành trình từ ngây ngô đến chín chắn.","youtube":"https://www.youtube.com/watch?v=EUEUZDV-in0"},{"name":"Đi Về Nhà","desc":"Trưởng thành là biết rằng: dù đi đâu, làm gì, nhà vẫn là nơi để trở về – và nhà đầu tiên là chính bạn. Giai điệu ấm áp, lời ca như cái ôm.","youtube":"https://www.youtube.com/watch?v=vTJdVE_gjI0"},{"name":"Lạ Lùng","desc":"Giai điệu mơ màng, lời ca như thơ: ''Lạ lùng là khi ta lớn lên, nhưng vẫn giữ được trái tim trẻ''. Trưởng thành không phải đánh mất sự ngây thơ, mà là biết trân trọng nó.","youtube":"https://www.youtube.com/watch?v=jv7WQeIPGjY"},{"name":"Sau Này Hãy Gặp Lại Nhau Khi Hoa Nở","desc":"Lời tạm biệt đẹp nhất: ''Sau này hãy gặp lại nhau khi cả hai đã trưởng thành''. Một bài hát về hy vọng – rằng trưởng thành sẽ dẫn ta đến những điều tốt đẹp hơn.","youtube":"https://www.youtube.com/watch?v=3rIZ9o1Hq9E"},{"name":"Một Nhà","desc":"Kết thúc bằng giấc mơ trưởng thành: ''Rồi một ngày ta sẽ có một nhà''. Giai điệu vui tươi, lời ca ấm áp – trưởng thành là xây dựng tương lai, chứ không chỉ sống với quá khứ.","youtube":"https://www.youtube.com/watch?v=TKlXc3iywoM"}]'::jsonb,
    'Reflective',
    'Playlist trưởng thành Khi Ta Đủ Lớn Để Hiểu Mình không chỉ là âm nhạc – mà là một hành trình lớn lên cùng bạn. Từ những lời rap tự sự của Đen Vâu, những giai điệu buồn nhẹ của Vũ, đến những hy vọng dịu dàng của Phan Mạnh Quỳnh – mỗi bài hát là một cột mốc trên con đường trưởng thành. Đây là nơi để bạn: /n- Nhìn lại những lần vấp ngã /n- Chấp nhận bản thân đã khác /n- Buông bỏ những điều không còn thuộc về mình /n- Bước tiếp với trái tim mạnh mẽ hơn /n/nTrưởng thành không phải là đích đến, mà là hành trình bạn chọn mỗi ngày. /nHãy bật playlist này khi bạn cần một người bạn âm nhạc để nhắc nhở: Bạn đã lớn hơn bạn nghĩ, và bạn xứng đáng với một tương lai đẹp đẽ. /nDành cho những người trẻ đang trưởng thành – và sẽ còn trưởng thành mãi.',
    950,
    '2025-10-20'
)
ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    "desc" = EXCLUDED."desc",
