INSERT INTO public.playlists_music (
    slug, title, "desc", description, keywords, categories,
    image, banner, songs, mood, final, views, date
) VALUES (
    'nhac-tre-cuoi-hay-nhat-cho-le-cuoi',
    '20 Bài Nhạc Trẻ Cưới Hay Nhất – Ngọt Ngào, Hiện Đại, Cảm Xúc Dâng Trào',
    'Khám phá tuyển tập 20 bài nhạc trẻ cưới hay nhất, kết hợp giữa những bản ballad cảm xúc và giai điệu sôi động hiện đại, lý tưởng cho ngày trọng đại của bạn.',
    'Bộ sưu tập 20 ca khúc nhạc trẻ nổi bật 2025, kết hợp giữa những bản ballad cảm xúc và các giai điệu sôi động hiện đại. Mỗi bài hát được lựa chọn dựa trên xu hướng Vpop mới nhất, tạo nên playlist hoàn hảo cho mọi khoảnh khắc trong lễ cưới.

Danh sách được thiết kế để sử dụng linh hoạt theo từng phần của buổi lễ: đón khách, bước vào lễ đường, trao nhẫn, chụp hình và tiệc mừng. Mỗi ca khúc đều có mô tả ngắn gợi ý thời điểm sử dụng, đảm bảo mang đến không khí trang trọng nhưng vẫn trẻ trung và tràn đầy năng lượng.

Phù hợp cho:
- Lễ cưới hiện đại tại nhà hàng, resort hoặc ngoài trời
- Cặp đôi yêu thích nhạc trẻ, Vpop và những bản hit viral
- Các buổi tiệc cần sự kết hợp giữa cảm xúc nhẹ nhàng và không khí sôi động
- Khách mời nhiều độ tuổi, dễ nghe – dễ hòa mình

Tất cả bài hát đều được đính kèm link YouTube chính thức, chất lượng cao, thuận tiện cho DJ hoặc điều phối âm thanh giúp tạo nên một trải nghiệm âm nhạc trọn vẹn và thống nhất.',
    '["nhạc trẻ cưới hay nhất","bài hát đám cưới nhạc trẻ","playlist nhạc trẻ cưới","nhạc cưới Vpop hiện đại","nhạc trẻ lễ cưới 2025","nhạc trẻ đám cưới viral","nhạc trẻ lễ cưới cảm xúc"]'::jsonb,
    '[{"name":"Nhạc Việt"},{"name":"Đám cưới"},{"name":"Ngày vui"}]'::jsonb,
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    '[{"name":"Ấm – Sweet Liqour","desc":"Giai điệu chill hiện đại, mang cảm giác ấm cúng và nhẹ nhàng; rất hợp mở đầu buổi lễ hoặc khi đón khách vào hội trường.","youtube":"https://youtu.be/NFDLWdNj26w?si=UtSMvXcJc04-Wbiv"},{"name":"Một Nhà – Da LAB","desc":"Giai điệu ấm áp, ca từ hạnh phúc về tổ ấm mới, cực hợp mở đầu lễ cưới hoặc phần giới thiệu cô dâu – chú rể.","youtube":"https://youtu.be/TKlXc3iywoM?si=JcSNNQ93BF4yKLIp"},{"name":"Nơi Này Có Anh – Sơn Tùng M-TP","desc":"Nhẹ nhàng, lãng mạn; mang cảm giác bình yên và trọn vẹn, phù hợp khi chiếu ảnh hoặc đón khách.","youtube":"https://youtu.be/FN7ALfpGxiI?si=ZikXerjeHyAEErrf"},{"name":"Hơn Cả Yêu – Đức Phúc","desc":"Ballad ngọt ngào biểu tượng của đám cưới Việt, tạo không khí trang trọng và xúc động trong khoảnh khắc trao nhẫn.","youtube":"https://youtu.be/__kGJZ-kPno?si=aEZ9a5b4uo2MhDNb"},{"name":"Đám Cưới Nha – Hồng Thanh x MIE","desc":"Vui tươi, trẻ trung, khuấy động không khí tiệc mừng và tạo năng lượng tích cực cho toàn hội trường.","youtube":"https://youtu.be/1mQwr_O81a4?si=uNjCRIGjIZ4JieWP"},{"name":"Gác Lại Âu Lo – Da LAB x Miu Lê","desc":"Tinh thần lạc quan, nhẹ nhàng; thích hợp làm nhạc nền khi đón khách hoặc chuyển cảnh chương trình.","youtube":"https://youtu.be/ECxVfrwwTp0?si=jnTWnqTFkSowVQBZ"},{"name":"Cầu Hôn – Văn Mai Hương","desc":"Lãng mạn như lời tỏ bạch; lý tưởng cho khoảnh khắc trao nhẫn, bước vào lễ đường hoặc công bố cặp đôi.","youtube":"https://youtu.be/po_jKn33cus?si=1QAIlJIOoh_dBb6v"},{"name":"Em Đồng Ý (I Do) – Đức Phúc x 911","desc":"Giai điệu trong trẻo, ca từ ''I Do'' rất hợp cho nghi thức chính của buổi lễ hoặc khi ký giấy kết hôn.","youtube":"https://youtu.be/IOe0tNoUGv8?si=JEx23ku-t7ebdCn7"},{"name":"Hôn Anh – MIN","desc":"Ballad hiện đại, cảm xúc; phù hợp lúc chụp ảnh, catwalk nhẹ nhàng hoặc đi cùng khoảnh khắc thân mật.","youtube":"https://youtu.be/7c39lfT6Sr0?si=yc0YSTxiDz8PQMA-"},{"name":"Cảm Ơn Tình Yêu – Uyên Linh","desc":"Nhẹ nhàng, sâu lắng; thích hợp cho phần tri ân hoặc khi cô dâu – chú rể gửi lời cảm ơn đến hai bên gia đình.","youtube":"https://youtu.be/UCX_RhPygOM?si=9ZA7roZHjvOiNp-i"},{"name":"Ta Là Của Nhau – Đông Nhi x Ông Cao Thắng","desc":"Mang thông điệp gắn kết và chung đôi, rất phù hợp để phát khi giới thiệu cặp đôi hoặc trong slideshow kỷ niệm.","youtube":"https://youtu.be/Qqix3_681pI?si=TOchv7rFKf8jlH5T"},{"name":"See Tình – Hoàng Thùy Linh","desc":"Sôi động, vui tươi; cực hợp cho phần tiệc, nhảy múa hoặc tạo vibe trẻ trung, hiện đại.","youtube":"https://youtu.be/gJHSDZfJrRY?si=K6BuFd1BruWAz-gK"},{"name":"Hãy Yêu Anh – Bùi Anh Tuấn","desc":"Ballad ngọt, mượt; phù hợp cho phần tâm tình, chiếu ảnh kỷ niệm hoặc màn slow dance nhẹ.","youtube":"https://youtu.be/GtLWMYVST-I?si=EbhiZuBA6URxzm0b"},{"name":"Ánh Nắng Của Anh – Đức Phúc","desc":"Giai điệu tươi sáng, ca từ đẹp như lời chúc phúc; phù hợp đón khách hoặc mở đầu tiệc.","youtube":"https://youtu.be/1P4DaXgzVnE?si=g1gCNBsQR5ZINXa6"},{"name":"Phía Cuối Con Đường – Thùy Chi ft. M4U","desc":"Chậm rãi, sâu sắc; hợp làm nhạc nền cho video hành trình yêu hoặc khoảnh khắc tri ân.","youtube":"https://youtu.be/OiH87roofiM?si=COmQnrc8tlFEsivx"},{"name":"Một Ngày Hay Trăm Năm – Văn Mai Hương","desc":"Nhẹ nhàng, tinh tế; phù hợp cho phần bế mạc hoặc khi cô dâu – chú rể nói lời cảm ơn.","youtube":"https://youtu.be/_4CiX0waEr0?si=TknSPJ41k7DsdzGK"},{"name":"Vợ Tuyệt Vời Nhất – Vũ Duy Khánh","desc":"Vui và cảm xúc; thích hợp khi chú rể dành tặng cô dâu hoặc lúc trao quà bất ngờ.","youtube":"https://youtu.be/oM_JJIJygYw?si=ayqutIjDUsBKd1zw"},{"name":"Cô Dâu – Ái Phương","desc":"Ballad trang trọng dành riêng cho khoảnh khắc cô dâu bước vào lễ đường hoặc catwalk ra mắt họ hàng.","youtube":"https://youtu.be/GSIkPUP1PoE?si=vvBx5_262QzAIvLZ"},{"name":"Thời Thanh Xuân Sẽ Qua – Phạm Hồng Phước x Văn Mai Hương","desc":"Hoài niệm, cảm xúc; phù hợp chiếu ảnh kỷ niệm hoặc làm nhạc nền phần chia sẻ.","youtube":"https://youtu.be/lCvZSI7XJ_g?si=y-iGV31TILEqM1MP"},{"name":"Sau Tất Cả – Erik","desc":"Bản tình ca vượt qua thử thách để cùng nhau đi đến cuối con đường, rất hợp cho phần kết lễ đầy ý nghĩa.","youtube":"https://youtu.be/wHF3Jv6Gk2o?si=LJnJoM7clOOowM8H"}]'::jsonb,
    'Ngọt ngào – Hiện đại – Cảm xúc',
    'Bộ playlist 20 ca khúc nhạc trẻ 2025 mang đến hành trình cảm xúc trọn vẹn cho ngày cưới – nơi từng giai điệu như ghi lại khoảnh khắc yêu thương thật đẹp. Từ những tiếng đàn mở đầu nhẹ như hơi thở, cho đến những đoạn cao trào khiến trái tim muốn hòa nhịp, tất cả tạo nên một không gian âm nhạc chạm đến cảm giác thân quen, ấm áp mà vẫn rất hiện đại.

Khi bật playlist này, bạn sẽ cảm nhận rõ sự chuyển mình của không khí: sự hồi hộp lúc cô dâu bước vào, sự dịu dàng khi hai người trao nhau ánh nhìn, rồi cả niềm vui rộn ràng lan tỏa trong từng bàn tiệc. Âm nhạc không chỉ làm đầy không gian, mà còn làm đầy cảm xúc – như thể mỗi bài hát đều đang kể lại câu chuyện tình yêu của chính bạn.

Đây không chỉ là danh sách bài hát, mà là một bức tranh cảm xúc được vẽ bằng âm thanh. Một chút ngọt ngào, một chút hân hoan, một chút trẻ trung – tất cả hòa quyện để biến ngày cưới thành một ký ức trọn vẹn, dịu dàng và khó quên.',
    21500,
    '2025-11-19'
)
